const D = { density: .5, energy: .6, trail: .5, scale: 1, speed: 1, hue: 190, x: .5, y: .5, style: 'neon-highways', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// --- coarse grid sized from scale (cache buffer+arrays in S, keyed on dims) ---
const GW = Math.max(72, Math.min(210, Math.round(174 / P.scale)));
const GH = Math.max(46, Math.min(150, Math.round(GW * height / width)));
const N = GW * GH;
const gkey = GW + 'x' + GH;
const MAXA = 16;
const dx = [0, 1, 0, -1], dy = [-1, 0, 1, 0];
const RULES = ['RL', 'RLR', 'LLRR', 'RRLL', 'LRRRRRLLR', 'LLRRRLRLRLLR', 'RLLR', 'RRLRLLLR'];

if (!S.g || S.gkey !== gkey) {
  S.g = createGraphics(GW, GH); S.g.pixelDensity(1);
  S.st = new Uint8Array(N);            // automaton cell state (interpreted mod nStates)
  S.heat = new Float32Array(N);        // scalar visit intensity (drives most styles)
  S.tr = new Float32Array(N * 3);      // accumulated ant RGB (drives neon interference)
  S.ants = new Array(MAXA);
  for (let i = 0; i < MAXA; i++) S.ants[i] = { x: 0, y: 0, dir: 0, hoff: (i * 137.508) % 360, life: 0, lifeMax: 1600, r: 1, g: 1, b: 1 };
  S.gkey = gkey; S.needSeed = true;
}

// --- deterministic hashes ---
function fr(i) { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); }
function frn() { S.rc = (S.rc + 1) | 0; const s = Math.sin(S.rc * 92.7 + P.seed * 311.7 + 17.3) * 43758.5453; return s - Math.floor(s); }

// rule for this frame (drifts by section = dramaturgy)
const rule = RULES[(K.section | 0) % RULES.length];
const rlen = rule.length;
const turns = new Int8Array(rlen);
for (let i = 0; i < rlen; i++) turns[i] = rule.charCodeAt(i) === 82 ? 1 : 3; // 'R'->+1, else left(+3)

const dep = 0.46;

function reseed(ant) {
  const cx = Math.round(P.x * GW + (frn() * 2 - 1) * GW * 0.34);
  const cy = Math.round(P.y * GH + (frn() * 2 - 1) * GH * 0.34);
  ant.x = ((cx % GW) + GW) % GW;
  ant.y = ((cy % GH) + GH) % GH;
  ant.dir = (frn() * 4) | 0;
  ant.life = 0;
  ant.lifeMax = 1600 + (frn() * 5200) | 0;
  // clear a small patch of automaton state -> fresh chaos burst -> new highway
  const rad = 4;
  for (let oy = -rad; oy <= rad; oy++) for (let ox = -rad; ox <= rad; ox++) {
    const gx = ((ant.x + ox) % GW + GW) % GW, gy = ((ant.y + oy) % GH + GH) % GH;
    S.st[gy * GW + gx] = 0;
  }
}

function step(ant) {
  const idx = ant.y * GW + ant.x;
  const c = S.st[idx] % rlen;
  ant.dir = (ant.dir + turns[c] + 4) % 4;
  S.st[idx] = (c + 1) % rlen;
  // deposit colored trail + heat at current cell
  S.heat[idx] = Math.min(1.5, S.heat[idx] + dep);
  const b = idx * 3;
  S.tr[b] = Math.min(1.9, S.tr[b] + ant.r * dep);
  S.tr[b + 1] = Math.min(1.9, S.tr[b + 1] + ant.g * dep);
  S.tr[b + 2] = Math.min(1.9, S.tr[b + 2] + ant.b * dep);
  // advance (toroidal)
  ant.x = (ant.x + dx[ant.dir] + GW) % GW;
  ant.y = (ant.y + dy[ant.dir] + GH) % GH;
  ant.life++;
  if (ant.life > ant.lifeMax) reseed(ant);
}

// pure HSB(sat=1,val=1) -> rgb 0..1
function h2rgb(h) {
  h = ((h % 360) + 360) % 360 / 60;
  const i = Math.floor(h), x = 1 - Math.abs((h % 2) - 1);
  if (i === 0) return [1, x, 0]; if (i === 1) return [x, 1, 0]; if (i === 2) return [0, 1, x];
  if (i === 3) return [0, x, 1]; if (i === 4) return [x, 0, 1]; return [1, 0, x];
}

const nAnts = Math.max(2, Math.min(MAXA, Math.round(4 + P.density * 11)));

// --- (re)seed + warmup so the very first frame is already populated ---
if (S.needSeed || S.seedUsed !== P.seed) {
  S.needSeed = false; S.seedUsed = P.seed; S.rc = 1; S.build = 0;
  S.st.fill(0); S.heat.fill(0); S.tr.fill(0);
  for (let i = 0; i < MAXA; i++) reseed(S.ants[i]);
  const warm = 4600;
  for (let s = 0; s < warm; s++) {
    const a = S.ants[s % nAnts];
    a.r = 1; a.g = 1; a.b = 1;
    step(a);
  }
}

// --- per-frame ant colors (respond to live hue/section drift) ---
const hueDrift = (K.section | 0) * 17;
for (let i = 0; i < nAnts; i++) {
  const a = S.ants[i];
  const c = h2rgb(P.hue + a.hoff + hueDrift);
  a.r = c[0]; a.g = c[1]; a.b = c[2];
}

// --- decay trails (persistence from P.trail) + cheap saturation census ---
const decay = 0.947 + P.trail * 0.037;   // ~0.947 (short veins) .. ~0.984 (long highways)
let satCount = 0;
for (let i = 0; i < N; i++) {
  const hv = (S.heat[i] *= decay);
  if (hv > 1.15) satCount++;
  const b = i * 3;
  S.tr[b] *= decay; S.tr[b + 1] *= decay; S.tr[b + 2] *= decay;
}
// auto-exposure: only bites when the field floods (protects extreme param combos from white-out)
const satFrac = satCount / N;
const expoScale = satFrac > 0.32 ? Math.max(0.45, 1 - (satFrac - 0.32) * 1.4) : 1;

// --- advance the colony (K gates steps/frame; audio adds on top; baseline never 0) ---
const kdrive = 0.55 + 0.55 * (K.swell || 0) + 0.5 * (K.intensity != null ? K.intensity : 0.5);
let steps = Math.round(P.energy * 24 * P.speed * kdrive + A.bass * 24);
steps = Math.max(3, Math.min(88, steps));
for (let s = 0; s < steps; s++) for (let i = 0; i < nAnts; i++) step(S.ants[i]);
// colony collapse: when the grid is over-built, wipe automaton memory + rescatter ants
// (recipe: "reseed when they build too much") -> restarts the chaos->highway->rebirth arc.
// visible trails keep fading through it (no strobe), but ant behavior renews.
S.build = (S.build || 0) + steps * nAnts;
if (S.build > N * 11) { S.build = 0; S.st.fill(0); for (let i = 0; i < MAXA; i++) reseed(S.ants[i]); }

// --- render buffer ---
const style = P.style;
const expo = (0.55 + P.energy * 0.9 + (K.intensity != null ? K.intensity : 0.5) * 0.3 + A.rms * 0.6) * expoScale;
const scanRoll = K.t * 6.0;
const g = S.g; g.loadPixels(); const px = g.pixels;
for (let idx = 0; idx < N; idx++) {
  const h = S.heat[idx];
  let R, G, B;
  if (style === 'phosphor') {
    const v = 1 - Math.exp(-h * expo * 1.55);
    const row = (idx / GW) | 0;
    const sl = 0.70 + 0.30 * Math.sin((row + scanRoll) * 1.9);
    R = 0.012 + 0.10 * v; G = 0.032 + v * sl; B = 0.020 + 0.30 * v;
  } else if (style === 'ink-plotter') {
    const d = 1 - Math.exp(-h * expo * 1.5);
    R = 0.93 * (1 - d) + 0.07 * d; G = 0.90 * (1 - d) + 0.09 * d; B = 0.81 * (1 - d) + 0.17 * d;
  } else if (style === 'heatmap') {
    const v = Math.min(1.15, h * expo * 0.95);
    R = Math.min(1, v * 2.3) + Math.max(0, 0.22 - v) * 0.55;
    G = Math.min(1, Math.max(0, v * 2.2 - 0.72));
    B = Math.min(1, Math.max(0, v * 4.0 - 2.85)) + Math.max(0, 0.30 - v) * 0.7;
  } else if (style === 'circuit') {
    const v = 1 - Math.exp(-h * expo * 1.55);
    R = 0.028 + v * 0.72; G = 0.075 + v * 0.44; B = 0.045 + v * 0.16;
    if (h > 1.05) { const vv = Math.min(1, (h - 1.05) * 2.2); R += vv * 0.28; G += vv * 0.36; B += vv * 0.16; }
  } else { // neon-highways (default)
    const b = idx * 3;
    const tr0 = S.tr[b], tr1 = S.tr[b + 1], tr2 = S.tr[b + 2];
    const bloom = (h > 1.05) ? Math.min(0.18, (h - 1.05) * 0.4) : 0; // hot cores whiten
    R = 0.075 + (1 - Math.exp(-tr0 * expo * 1.25)) * 0.92 + bloom;
    G = 0.092 + (1 - Math.exp(-tr1 * expo * 1.25)) * 0.92 + bloom;
    B = 0.150 + (1 - Math.exp(-tr2 * expo * 1.25)) * 0.92 + bloom;
  }
  const o = idx * 4;
  px[o] = R < 0 ? 0 : R > 1 ? 255 : R * 255;
  px[o + 1] = G < 0 ? 0 : G > 1 ? 255 : G * 255;
  px[o + 2] = B < 0 ? 0 : B > 1 ? 255 : B * 255;
  px[o + 3] = 255;
}
g.updatePixels();
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
